import React, { useState } from 'react';
import memelogo from '../assets/memecoin.png';
import Wallet from './Wallet';
import { FaWallet, FaArrowDown } from 'react-icons/fa';

const Navbar = () => {
  const [isWalletOpen, setIsWalletOpen] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [walletAddress, setWalletAddress] = useState('0x...BAa8');

  const handleDisconnect = () => {
    setWalletAddress('');
    setIsDropdownOpen(false);
  };

  return (
    <>
      <nav className="bg-gradient-to-r from-[#0B041A] to-[#361480] px-6 py-2">
        <div className="container mx-auto flex items-center justify-between">
          <div className="flex items-center">
            <img src={memelogo} alt="Memecoin Logo" className="h-[93px] w-auto" />
          </div>
          
          <div className="flex items-center space-x-8">
            <NavLink text="Home" />
            <NavLink text="Trade" highlight={true} />
            <NavLink text="Market" />
            <NavLink text="About" />
            <NavLink text="Developers" />
            
            <div className="relative">
              <button 
                className="flex items-center px-4 py-2 rounded-full bg-mystery-accent text-white hover:opacity-90 transition-opacity"
                onMouseEnter={() => setIsDropdownOpen(true)}
                onMouseLeave={() => setIsDropdownOpen(false)}
              >
                <FaArrowDown className="mr-2" />
                <span>{walletAddress || 'Link Wallet'}</span>
                <FaWallet className="ml-2" />
              </button>
              {isDropdownOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white text-black rounded-lg shadow-lg z-10">
                  <ul>
                    <li className="px-4 py-2 hover:bg-gray-200 cursor-pointer">Recent Transactions</li>
                    <li 
                      className="px-4 py-2 hover:bg-gray-200 cursor-pointer"
                      onClick={handleDisconnect}
                    >
                      Disconnect
                    </li>
                  </ul>
                </div>
              )}
            </div>
          </div>
        </div>
      </nav>

      <Wallet 
        isOpen={isWalletOpen}
        onClose={() => setIsWalletOpen(false)}
      />
    </>
  );
};

const NavLink = ({ text, highlight = false }) => (
  <a
    href="#"
    className={`font-heading text-lg ${
      highlight 
        ? 'text-mystery-highlight' 
        : 'text-white hover:text-mystery-accent'
    } transition-colors`}
  >
    {text}
  </a>
);

export default Navbar;
